{
  "propositions": [
    {
      "id": "P1",
      "proposition": "The new section defines \"early warning signs\" as evidence of student safety, health, or behavioral issues, including but not limited to engaging in or being the victim of harassment, intimidation, bullying, or cyberbullying; making or receiving threats of violence; and signs of substance abuse, mental health issues, self-harm, or suicidal ideation.",
      "importance": "supporting",
      "section": "SECTION 1(b)",
      "source_quote": "\"early warning signs\" means evidence of safety,"
    },
    {
      "id": "P2",
      "proposition": "Each LEA and public charter school must implement a computer-based system that teachers and school staff must use to enter data on early warning signs demonstrated by enrolled students, subject to the exemption in subsection (i).",
      "importance": "core",
      "section": "SECTION 1(c)",
      "source_quote": "Each LEA and public charter school shall implement a computer-based"
    },
    {
      "id": "P3",
      "proposition": "Each LEA and public charter school must ensure that every teacher and school staff member is trained to identify early warning signs and enter data into the computer-based system, subject to the exemption in subsection (i).",
      "importance": "supporting",
      "section": "SECTION 1(c)",
      "source_quote": "each teacher and school staff member is trained"
    },
    {
      "id": "P4",
      "proposition": "The computer-based system must align with the LEA's harassment, intimidation, bullying, and cyberbullying policy adopted under § 49-6-4503, the School Discipline Act, and each school safety plan adopted by the LEA or public charter school under the SAVE Act.",
      "importance": "supporting",
      "section": "SECTION 1(d)(1)",
      "source_quote": "Align with the harassment, intimidation, bullying, and cyberbullying"
    },
    {
      "id": "P5",
      "proposition": "The computer-based system must include a database capable of receiving and maintaining student data entered by teachers and school staff concerning students' early warning signs.",
      "importance": "supporting",
      "section": "SECTION 1(d)(2)",
      "source_quote": "Include a database that is capable of receiving and maintaining"
    },
    {
      "id": "P6",
      "proposition": "When an early warning sign is entered for a student, the system must immediately notify the LEA personnel serving on its threat assessment team created under § 49-6-2701 or the public charter school's employee designated to receive the notification.",
      "importance": "core",
      "section": "SECTION 1(d)(3)",
      "source_quote": "Immediately notify the LEA personnel serving on the LEA's threat"
    },
    {
      "id": "P7",
      "proposition": "LEA or public charter school personnel receiving an early-warning-sign notification must review it and all previously received notifications for that student and determine whether further action is needed to address the student's behavior, subject to the exemption in subsection (i).",
      "importance": "core",
      "section": "SECTION 1(e)",
      "source_quote": "determine whether further action is needed to address the student's behavior."
    },
    {
      "id": "P8",
      "proposition": "Each LEA and public charter school must annually report to the department of education data collected during the immediately preceding school year, including the total number of early warning signs entered into the system.",
      "importance": "core",
      "section": "SECTION 1(f)(1), (f)(1)(A)",
      "source_quote": "The number of early warning signs input into the system;"
    },
    {
      "id": "P9",
      "proposition": "The annual report must disaggregate early-warning-sign entries by whether a teacher or school staff member entered them, further disaggregating teacher entries by grade levels and subject areas taught and staff entries by position, assignment, and duties.",
      "importance": "supporting",
      "section": "SECTION 1(f)(1)(B)",
      "source_quote": "The number of early warning signs input into the system,"
    },
    {
      "id": "P10",
      "proposition": "The annual report must give the number of students with more than one early warning sign entered and the number of early warning signs entered for each such student.",
      "importance": "supporting",
      "section": "SECTION 1(f)(1)(C)",
      "source_quote": "The number of students for whom more than one (1)"
    },
    {
      "id": "P11",
      "proposition": "The annual report must generally describe the types of early warning signs entered and the LEA's or public charter school's actions in response to each entered sign; neither description may contain details or information allowing a student to be identified.",
      "importance": "supporting",
      "section": "SECTION 1(f)(1)(D)-(E)",
      "source_quote": "A general description of the actions taken by the LEA or"
    },
    {
      "id": "P12",
      "proposition": "Annual reports must not contain any details or information that would allow a student to be identified.",
      "importance": "supporting",
      "section": "SECTION 1(f)(2)",
      "source_quote": "details or information that would allow a student to be identified."
    },
    {
      "id": "P13",
      "proposition": "Reports made under the new section must comply with FERPA, § 10-7-504, the Data Accessibility, Transparency, and Accountability Act, and all other relevant privacy laws.",
      "importance": "supporting",
      "section": "SECTION 1(g)",
      "source_quote": "and all other relevant privacy laws."
    },
    {
      "id": "P14",
      "proposition": "If the commissioner of education finds an LEA or public charter school is not complying with the new section, the commissioner may withhold state funds in an amount the commissioner determines until the LEA or school complies.",
      "importance": "core",
      "section": "SECTION 1(h)",
      "source_quote": "not complying with this section, then the commissioner may withhold state funds, in an"
    },
    {
      "id": "P15",
      "proposition": "Subsections (c)-(e), governing system implementation, training, system requirements, and notification review, do not apply to an LEA or public charter school that implemented a system for documenting students' early warning signs before July 1, 2026, provided it continuously maintains and uses that system. The exemption does not extend to the reporting requirements.",
      "importance": "core",
      "section": "SECTION 1(i)",
      "source_quote": "Subsections (c)-(e) do not apply to an LEA or public charter school that"
    },
    {
      "id": "P16",
      "proposition": "The act takes effect July 1, 2026.",
      "importance": "supporting",
      "section": "SECTION 2",
      "source_quote": "This act takes effect July 1, 2026, the public welfare requiring it."
    }
  ]
}
